\end{tikzpicture}
\end{center} (в $\text{Вт}$).

На участке цепи, изображённом на рисунке, сопротивление каждого из четырёх резисторов равно $6\,\text{Ом}$. Каково общее сопротивление цепи между клеммами $\text{А}$ и $\text{В}$?
\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm,>=stealth,line width=0.8pt]
\draw (0,0) circle (0.06) node[left=4pt] {$\text{А}$};
\draw (0.06,0)--(0.8,0);
\draw (0.8,0)--(0.8,0.35)--(1.05,0.35);
\draw (1.05,0.18) rectangle (1.85,0.52);
\draw (1.85,0.35)--(2.1,0.35)--(2.1,0);
\draw (0.8,0)--(0.8,-0.35)--(1.05,-0.35);
\draw (1.05,-0.52) rectangle (1.85,-0.18);
\draw (1.85,-0.35)--(2.1,-0.35)--(2.1,0);
\fill (0.8,0) circle (0.055);
\fill (2.1,0) circle (0.055);
\draw (2.1,0)--(2.8,0);
\draw (2.8,-0.17) rectangle (3.6,0.17);
\draw (3.6,0)--(4.3,0);
\draw (4.3,-0.17) rectangle (5.1,0.17);
\draw (5.1,0)--(5.84,0);
\draw (5.9,0) circle (0.06) node[right=4pt] {$\text{В}$};
\end{tikzpicture}
\end{center} (в $\text{Ом}$).

\begin{center}
\begin{tikzpicture}[x=1cm,y=1cm,>=stealth,line width=0.8pt]
